import React, { useEffect, useState } from "react";
import Navbar from "../components/Navbar";

export default function Leaderboard() {
  const [students, setStudents] = useState([]);
  const [form, setForm] = useState({ name: "", photo: "", course: "", score: "" });
  const [editId, setEditId] = useState(null);

  const fetchStudents = async () => {
    const res = await fetch("http://localhost:8080/api/leaderboard");
    const data = await res.json();
    setStudents(data);
  };

  useEffect(() => {
    fetchStudents();
  }, []);

  const handleInputChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async () => {
    const res = await fetch("http://localhost:8080/api/student", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(form),
    });
    const data = await res.json();
    fetchStudents();
    setForm({ name: "", photo: "", course: "", score: "" });
  };

  const handleDelete = async (id) => {
    await fetch(`http://localhost:8080/api/student/${id}`, {
      method: "DELETE",
    });
    fetchStudents();
  };

  const handleEdit = (student) => {
    setForm(student);
    setEditId(student._id);
  };

  const handleUpdate = async () => {
    await fetch(`http://localhost:8080/api/student/${editId}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(form),
    });
    setEditId(null);
    setForm({ name: "", photo: "", course: "", score: "" });
    fetchStudents();
  };

  return (
    <div className="min-h-screen bg-blue-100 p-8 text-center">
      <Navbar />
      <h2 className="text-3xl font-bold mb-4 text-blue-700">🏆 Leaderboard (CRUD)</h2>

      <div className="max-w-md mx-auto bg-white p-4 mb-6 rounded shadow">
        <h3 className="text-lg font-semibold mb-2">{editId ? "✏️ Update Student" : "➕ Add Student"}</h3>
        <input name="name" placeholder="Name" value={form.name} onChange={handleInputChange}
          className="block w-full mb-2 p-2 border rounded" />
        <input name="photo" placeholder="Photo URL" value={form.photo} onChange={handleInputChange}
          className="block w-full mb-2 p-2 border rounded" />
        <input name="course" placeholder="Course" value={form.course} onChange={handleInputChange}
          className="block w-full mb-2 p-2 border rounded" />
        <input name="score" placeholder="Score" type="number" value={form.score} onChange={handleInputChange}
          className="block w-full mb-2 p-2 border rounded" />
        {editId ? (
          <button onClick={handleUpdate} className="bg-yellow-500 text-white px-4 py-2 rounded">Update</button>
        ) : (
          <button onClick={handleSubmit} className="bg-blue-500 text-white px-4 py-2 rounded">Add</button>
        )}
      </div>

      <div className="max-w-4xl mx-auto">
        {students.map((s, i) => (
          <div key={i} className="flex justify-between items-center bg-white mb-2 p-4 rounded shadow">
            <img src={`http://localhost:8080${s.photo}`} alt="avatar" className="w-12 h-12 rounded-full" />
            <span className="font-semibold">{s.name}</span>
            <span>{s.course}</span>
            <span className="font-bold text-blue-700">{s.score}</span>
            <button onClick={() => handleEdit(s)} className="text-yellow-600 hover:underline">Edit</button>
            <button onClick={() => handleDelete(s._id)} className="text-red-500 hover:underline">Delete</button>
          </div>
        ))}
      </div>
    </div>
  );
}
